function print(v) { __out.push(String(v)); }

    function f() { var x = "f"; return eval("x"); }
    function g() { var x = "g"; return eval("x"); }
    print(f() + g() + f() + g());
if (__out.join('\n') !== "fgfg") throw new Error('differential ' + __out.join('|'));

